create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text not null default '',referral_code text not null unique,created_at timestamptz not null default now());
create table if not exists public.wallets(user_id uuid primary key references public.profiles(id) on delete cascade,available_balance numeric(12,2) not null default 0,total_earned numeric(12,2) not null default 0,referral_earnings numeric(12,2) not null default 0,ad_earnings numeric(12,2) not null default 0,updated_at timestamptz not null default now());
create table if not exists public.referrals(id uuid primary key default gen_random_uuid(),referrer_id uuid not null references public.profiles(id) on delete cascade,referred_id uuid not null unique references public.profiles(id) on delete cascade,referral_code text not null,reward_amount numeric(12,2) not null default 150,status text not null default 'qualified' check(status in ('pending','qualified','rejected')),created_at timestamptz not null default now());
create table if not exists public.earning_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,type text not null check(type in ('referral','rewarded_ad','task','adjustment')),amount numeric(12,2) not null,status text not null default 'approved' check(status in ('pending','approved','reversed')),reference_id text,created_at timestamptz not null default now());
create table if not exists public.withdrawal_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,amount numeric(12,2) not null check(amount>0),payout_method text not null default 'upi',payout_address text not null,status text not null default 'pending' check(status in ('pending','approved','paid','rejected')),created_at timestamptz not null default now());
create or replace function public.make_referral_code() returns text language plpgsql as $f$declare c text;begin loop c:='POCK-'||upper(substr(encode(gen_random_bytes(5),'hex'),1,8));exit when not exists(select 1 from public.profiles where referral_code=c);end loop;return c;end$f$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $f$declare code text;refcode text;referrer uuid;begin code:=public.make_referral_code();insert into public.profiles(id,full_name,phone,referral_code) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.raw_user_meta_data->>'phone',''),code);insert into public.wallets(user_id) values(new.id);refcode:=nullif(new.raw_user_meta_data->>'referral_code_used','');if refcode is not null then select id into referrer from public.profiles where referral_code=refcode and id<>new.id limit 1;if referrer is not null then insert into public.referrals(referrer_id,referred_id,referral_code,reward_amount) values(referrer,new.id,refcode,150);update public.wallets set available_balance=available_balance+150,total_earned=total_earned+150,referral_earnings=referral_earnings+150,updated_at=now() where user_id=referrer;insert into public.earning_transactions(user_id,type,amount,status,reference_id) values(referrer,'referral',150,'approved',new.id::text);end if;end if;return new;end$f$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;alter table public.wallets enable row level security;alter table public.referrals enable row level security;alter table public.earning_transactions enable row level security;alter table public.withdrawal_requests enable row level security;
create policy "profile own" on public.profiles for select using(auth.uid()=id);create policy "wallet own" on public.wallets for select using(auth.uid()=user_id);create policy "referrals own" on public.referrals for select using(auth.uid()=referrer_id or auth.uid()=referred_id);create policy "transactions own" on public.earning_transactions for select using(auth.uid()=user_id);create policy "withdrawals own read" on public.withdrawal_requests for select using(auth.uid()=user_id);create policy "withdrawals own insert" on public.withdrawal_requests for insert with check(auth.uid()=user_id);
